// NULL-tolerant scan buffer for roundTeamScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type roundTeamPreloadBuf struct {
	ID      null.Val[int64]
	RoundID null.Val[int64]
	TeamKey null.Val[string]
	Rank    null.Val[int32]
}

// roundTeamScanMapperNullable maps the preloaded roundTeam
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func roundTeamScanMapperNullable(prefix string) scan.Mapper[*RoundTeam] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*RoundTeam, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *roundTeamPreloadBuf) any
		}
		targets := make([]target, 0, 4)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *roundTeamPreloadBuf) any { return &b.ID }})
			case "round_id":
				targets = append(targets, target{i, func(b *roundTeamPreloadBuf) any { return &b.RoundID }})
			case "team_key":
				targets = append(targets, target{i, func(b *roundTeamPreloadBuf) any { return &b.TeamKey }})
			case "rank":
				targets = append(targets, target{i, func(b *roundTeamPreloadBuf) any { return &b.Rank }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(roundTeamPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*RoundTeam, error) {
				buf := link.(*roundTeamPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.IsValue()) &&
					!(buf.RoundID.IsValue()) &&
					!(buf.TeamKey.IsValue()) &&
					!(buf.Rank.IsValue()) {
					return nil, nil
				}

				o := new(RoundTeam)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.RoundID.IsValue() {
					o.RoundID = buf.RoundID.MustGet()
				}
				if buf.TeamKey.IsValue() {
					o.TeamKey = buf.TeamKey.MustGet()
				}
				o.Rank = buf.Rank
				return o, nil
			}
	}
}

func (o *RoundTeam) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "RoundPlayers":
		rels, ok := retrieved.(RoundPlayerSlice)
		if !ok {
			return fmt.Errorf("roundTeam cannot load %T as %q", retrieved, name)
		}

		o.R.RoundPlayers = rels
		o.R.Loaded.RoundPlayers = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.RoundTeam = o
				rel.R.Loaded.RoundTeam = true
			}
		}
		return nil
	case "Round":
		rel, ok := retrieved.(*Round)
		if !ok {
			return fmt.Errorf("roundTeam cannot load %T as %q", retrieved, name)
		}

		o.R.Round = rel
		o.R.Loaded.Round = true

		if rel != nil {
			rel.R.RoundTeams = RoundTeamSlice{o}
		}
		return nil
	case "StatValues":
		rels, ok := retrieved.(StatValueSlice)
		if !ok {
			return fmt.Errorf("roundTeam cannot load %T as %q", retrieved, name)
		}

		o.R.StatValues = rels
		o.R.Loaded.StatValues = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.RoundTeam = o
				rel.R.Loaded.RoundTeam = true
			}
		}
		return nil
	default:
		return fmt.Errorf("roundTeam has no relationship %q", name)
	}
}

