// LoadCountRoundPlayers loads the count of RoundPlayers for a slice in a single batch query
func (os RoundTeamSlice) LoadCountRoundPlayers(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs

	pkID := make(pgtypes.Array[int64], 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		pkID = append(pkID, o.ID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkID), "bigint[]"))

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    int64
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			RoundPlayers.Columns.RoundTeamID.As("id"),
			psql.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(RoundPlayers.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(RoundPlayers.Columns.RoundTeamID.EQ(PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(RoundPlayers.Columns.RoundTeamID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		psql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[int64]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.RoundPlayers = &count
	}

	return nil
}

// LoadCountStatValues loads the count of StatValues into the C struct
func (o *RoundTeam) LoadCountStatValues(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.StatValues(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.StatValues = &count
	return nil
}

// LoadCountStatValues loads the count of StatValues for a slice in a single batch query
func (os RoundTeamSlice) LoadCountStatValues(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs

	pkID := make(pgtypes.Array[int64], 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		pkID = append(pkID, o.ID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkID), "bigint[]"))

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    int64
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			StatValues.Columns.RoundTeamID.As("id"),
			psql.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(StatValues.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(StatValues.Columns.RoundTeamID.EQ(PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(StatValues.Columns.RoundTeamID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		psql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[int64]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.StatValues = &count
	}

	return nil
}

type roundTeamJoins[Q dialect.Joinable] struct {
	typ          string
	RoundPlayers modAs[Q, roundPlayerColumns]
	Round        modAs[Q, roundColumns]
	StatValues   modAs[Q, statValueColumns]
}

func (j roundTeamJoins[Q]) aliasedAs(alias string) roundTeamJoins[Q] {
	return buildRoundTeamJoins[Q](buildRoundTeamColumns(alias), j.typ)
}

func buildRoundTeamJoins[Q dialect.Joinable](cols roundTeamColumns, typ string) roundTeamJoins[Q] {
	return roundTeamJoins[Q]{
		typ: typ,
		RoundPlayers: modAs[Q, roundPlayerColumns]{
			c: RoundPlayers.Columns,
			f: func(to roundPlayerColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, RoundPlayers.NameExpr().As(to.Alias())).On(
						to.RoundTeamID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Round: modAs[Q, roundColumns]{
			c: Rounds.Columns,
			f: func(to roundColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Rounds.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.RoundID),
					))
				}

				return mods
			},
		},
		StatValues: modAs[Q, statValueColumns]{
			c: StatValues.Columns,
			f: func(to statValueColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, StatValues.NameExpr().As(to.Alias())).On(
						to.RoundTeamID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
